<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$pdo=db();
if(is_post()){try{verify_csrf();$type=scalar_string($_POST['type']??'review');$id=max(0,scalar_int($_POST['id']??0));$status=scalar_string($_POST['status']??'pending');if($id<1||!in_array($status,['pending','approved','rejected'],true))throw new RuntimeException('درخواست معتبر نیست.');
    if($type==='review'){$reply=text_substr(trim(scalar_string($_POST['reply']??'')),0,3000);$find=$pdo->prepare('SELECT product_id FROM product_reviews WHERE id=?');$find->execute([$id]);$productId=(int)$find->fetchColumn();if($productId<1)throw new RuntimeException('دیدگاه پیدا نشد.');$pdo->prepare('UPDATE product_reviews SET status=?,admin_reply=?,replied_by=?,replied_at=IF(? IS NULL,NULL,NOW()) WHERE id=?')->execute([$status,$reply?:null,$reply!==''?(int)admin_user()['id']:null,$reply?:null,$id]);recalculate_product_rating($pdo,$productId);}
    else{$answer=text_substr(trim(scalar_string($_POST['answer']??'')),0,3000);$pdo->prepare('UPDATE product_questions SET status=?,answer=?,answered_by=?,answered_at=IF(? IS NULL,NULL,NOW()) WHERE id=?')->execute([$status,$answer?:null,$answer!==''?(int)admin_user()['id']:null,$answer?:null,$id]);}
    flash('success','وضعیت ذخیره شد.');
}catch(Throwable $e){flash('error',$e->getMessage());}redirect(app_url('admin/reviews.php'));}
$reviews=$pdo->query("SELECT r.*,p.title product_title,c.phone,c.full_name FROM product_reviews r JOIN products p ON p.id=r.product_id JOIN customers c ON c.id=r.customer_id ORDER BY FIELD(r.status,'pending','approved','rejected'),r.id DESC LIMIT 200")->fetchAll();
$questions=$pdo->query("SELECT q.*,p.title product_title,c.phone,c.full_name FROM product_questions q JOIN products p ON p.id=q.product_id JOIN customers c ON c.id=q.customer_id ORDER BY FIELD(q.status,'pending','approved','rejected'),q.id DESC LIMIT 200")->fetchAll();
$adminPage='reviews';$adminTitle='نظر و پرسش‌وپاسخ';require __DIR__.'/partials/header.php';?>
<div class="admin-title"><h1>نظر و پرسش‌وپاسخ</h1><span class="badge"><?=fa_number(count($reviews)+count($questions))?> مورد</span></div>
<div class="card"><h2>دیدگاه‌ها</h2><div class="table-wrap"><table><thead><tr><th>محصول / مشتری</th><th>امتیاز و متن</th><th>وضعیت و پاسخ</th></tr></thead><tbody><?php foreach($reviews as $row):?><tr><td><strong><?=e($row['product_title'])?></strong><br><?=e($row['full_name']?:$row['phone'])?><?php if($row['is_verified_purchase']):?><br><span class="badge">خریدار محصول</span><?php endif?></td><td><?=str_repeat('★',(int)$row['rating'])?><br><?=nl2br(e($row['body']))?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="type" value="review"><input type="hidden" name="id" value="<?=$row['id']?>"><select name="status"><option value="pending" <?=$row['status']==='pending'?'selected':''?>>در انتظار</option><option value="approved" <?=$row['status']==='approved'?'selected':''?>>تأیید</option><option value="rejected" <?=$row['status']==='rejected'?'selected':''?>>رد</option></select><textarea name="reply" maxlength="3000" placeholder="پاسخ فروشگاه"><?=e($row['admin_reply']??'')?></textarea><button class="btn btn-primary">ذخیره</button></form></td></tr><?php endforeach?><?php if(!$reviews):?><tr><td colspan="3">دیدگاهی ثبت نشده است.</td></tr><?php endif?></tbody></table></div></div>
<div class="card"><h2>پرسش‌ها</h2><div class="table-wrap"><table><thead><tr><th>محصول / مشتری</th><th>پرسش</th><th>وضعیت و پاسخ</th></tr></thead><tbody><?php foreach($questions as $row):?><tr><td><strong><?=e($row['product_title'])?></strong><br><?=e($row['full_name']?:$row['phone'])?></td><td><?=nl2br(e($row['question']))?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="type" value="question"><input type="hidden" name="id" value="<?=$row['id']?>"><select name="status"><option value="pending" <?=$row['status']==='pending'?'selected':''?>>در انتظار</option><option value="approved" <?=$row['status']==='approved'?'selected':''?>>تأیید</option><option value="rejected" <?=$row['status']==='rejected'?'selected':''?>>رد</option></select><textarea name="answer" maxlength="3000" placeholder="پاسخ فروشگاه"><?=e($row['answer']??'')?></textarea><button class="btn btn-primary">ذخیره</button></form></td></tr><?php endforeach?><?php if(!$questions):?><tr><td colspan="3">پرسشی ثبت نشده است.</td></tr><?php endif?></tbody></table></div></div>
<?php require __DIR__.'/partials/footer.php';
